(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-202":{scenario:{company:"Lotus Gate Trading",supervisor:{name:"Phạm Quang Huy",role:{vi:"Trưởng phòng Thủ tục Hải quan",en:"Customs Compliance Manager"}},ref_code:"TK-0942",title:{vi:"Đúng mã HS. Đúng trị giá. Đúng luật.",en:"Right HS code. Right value. Right law."},brief:{vi:"Bạn khai tờ khai nhập khẩu TK-0942 cho 400 máy pha cà phê gia dụng chạy điện. Hóa đơn ghi FOB 12000 USD, cước biển 600 USD, phí bảo hiểm 60 USD. Đối chiếu tờ khai nháp với bộ hồ sơ đã duyệt, sửa mã HS và số thuế nhập khẩu (thuế suất trong bài mô phỏng 20%), rồi lập báo cáo có căn cứ.",en:"You are filing import declaration TK-0942 for 400 electric household coffee makers. The invoice shows FOB 12000 USD, ocean freight 600 USD and insurance 60 USD. Compare the draft declaration with the approved file, correct the HS code and the import duty (training rate 20%), then write an evidence-based report."},reference_title:{vi:"Hồ sơ phân loại & trị giá đã duyệt · TK-0942",en:"Approved classification & valuation file · TK-0942"},fields:[{id:"HS_CODE",label:{vi:"Mã HS khai báo",en:"Declared HS code"},initial:"8509.40",expected:"8516.71",choices:["8509.40","8516.71","8419.81"],reference:"Phiếu phân loại HS",hint:{vi:"Đọc chú giải chương 85: máy pha cà phê gia dụng gia nhiệt bằng điện thuộc nhóm 85.16.",en:"Read the Chapter 85 notes: electro-thermic household coffee makers fall under heading 85.16."}},{id:"DUTY_USD",label:{vi:"Thuế nhập khẩu (USD)",en:"Import duty (USD)"},initial:"2400",expected:"2532",reference:"Bảng tính trị giá hải quan",ref_value:{vi:"Trị giá tính thuế = FOB 12000 + cước 600 + bảo hiểm 60; thuế suất 20%",en:"Customs value = FOB 12000 + freight 600 + insurance 60; duty rate 20%"},hint:{vi:"Trị giá tính thuế nhập khẩu phải cộng cước và bảo hiểm đến cửa khẩu nhập đầu tiên.",en:"The dutiable value must include freight and insurance to the first port of import."}}],sop32:{vi:"Trị giá hải quan = giá FOB + cước vận tải + phí bảo hiểm đến cửa khẩu nhập; thuế nhập khẩu = trị giá hải quan x thuế suất (bài mô phỏng 20%).",en:"Customs value = FOB price + freight + insurance to the port of import; import duty = customs value x duty rate (training rate 20%)."},context:{label:"TỜ KHAI NHÁP / TK-0942",metrics:[{label:{vi:"Giá FOB",en:"FOB price"},value:"12,000 USD"},{label:{vi:"Cước + bảo hiểm",en:"Freight + insurance"},value:"660 USD"},{label:{vi:"Thuế suất mô phỏng",en:"Training duty rate"},value:"20%"}]},crisis:{vi:"Phòng kinh doanh nhắn: “Khai mã 8509.40 cho thuế thấp hơn đi, hải quan ít khi kiểm tra lô nhỏ. Lô hàng phải thông quan trong chiều nay.”",en:"Sales messages you: “Declare 8509.40 to get a lower rate, customs rarely inspects small shipments. The goods must clear this afternoon.”"},options:{safe:{vi:"Khai đúng mã 8516.71 theo hồ sơ phân loại, giải trình bằng tài liệu kỹ thuật và báo trưởng phòng; nếu còn băn khoăn thì đề nghị xác định trước mã số.",en:"Declare the correct code 8516.71 per the classification file, support it with technical documents and inform the manager; request an advance ruling if doubt remains."},shortcut:{vi:"Khai mã 8509.40 cho kịp giờ, nếu bị kiểm tra thì khai bổ sung sau.",en:"Declare 8509.40 to meet the deadline and amend later if customs checks."},wait:{vi:"Tạm dừng khai báo và chờ kinh doanh tự quyết định mã HS.",en:"Stop filing and wait for Sales to decide the HS code."}},questions:{vi:["Vì sao chọn mã 8516.71 thay vì 8509.40? Hồ sơ nào chứng minh phân loại của bạn?","Trình bày cách tính trị giá hải quan và rủi ro nếu tính thuế trên giá FOB."],en:["Why did you choose 8516.71 instead of 8509.40? Which documents support your classification?","Explain how you calculated the customs value and the risk of computing duty on the FOB price."]},hints:{vi:["Đặt bản nháp cạnh phiếu phân loại HS và đánh dấu dòng mã số đang sai.","Cộng đủ FOB, cước và bảo hiểm trước khi nhân thuế suất ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi áp lực đổi mã HS phải được báo cáo, không được khai sai."],en:["Place the draft next to the HS classification sheet and flag the wrong code line.","Add FOB, freight and insurance before applying the rate in SOP 3.2.","Re-read SOP 4.2: any pressure to change the HS code must be escalated, never misdeclared."]}},learning:{summary:{vi:"Chuyên viên khai báo hải quan điện tử lập và nộp tờ khai xuất nhập khẩu trên hệ thống VNACCS/VCIS, phân loại hàng hóa theo mã HS, xác định trị giá hải quan, tính thuế và xử lý phản hồi của cơ quan hải quan. Công việc đòi hỏi đọc hiểu chứng từ thương mại, nắm chắc quy định và giữ hồ sơ đủ căn cứ để sẵn sàng kiểm tra sau thông quan.",en:"A customs declaration specialist prepares and submits import and export declarations on VNACCS/VCIS, classifies goods by HS code, determines customs value, calculates duties and handles customs feedback. The role requires reading trade documents, knowing the regulations and keeping a well-evidenced file ready for post-clearance audit."},responsibilities:{vi:["Kiểm tra bộ chứng từ: hợp đồng, hóa đơn, phiếu đóng gói, vận đơn, C/O trước khi khai.","Phân loại hàng hóa theo Danh mục HS và 6 quy tắc tổng quát giải thích.","Xác định trị giá hải quan, tính thuế nhập khẩu, thuế GTGT và các khoản thuế khác.","Truyền tờ khai, theo dõi phân luồng xanh, vàng, đỏ và phối hợp kiểm tra thực tế.","Lưu trữ hồ sơ, khai bổ sung đúng hạn và chuẩn bị cho kiểm tra sau thông quan."],en:["Check the document set: contract, invoice, packing list, bill of lading and C/O before filing.","Classify goods using the HS nomenclature and the six General Interpretative Rules.","Determine customs value and calculate import duty, VAT and other taxes.","Submit declarations, follow green, yellow and red channel results and coordinate physical inspections.","Archive files, file amendments on time and prepare for post-clearance audits."]},competencies:[{name:{vi:"Phân loại HS",en:"HS classification"},desc:{vi:"Áp dụng chú giải phần, chương và quy tắc tổng quát để chọn mã 8 số chính xác.",en:"Apply section and chapter notes plus the general rules to choose the correct 8-digit code."}},{name:{vi:"Trị giá hải quan",en:"Customs valuation"},desc:{vi:"Xác định trị giá giao dịch, các khoản phải cộng, được trừ và phương pháp thay thế khi cần.",en:"Determine transaction value, required additions and deductions, and fallback methods when needed."}},{name:{vi:"Đọc chứng từ thương mại",en:"Trade document review"},desc:{vi:"Phát hiện sai lệch giữa hóa đơn, phiếu đóng gói, vận đơn và hợp đồng.",en:"Spot discrepancies between invoice, packing list, bill of lading and contract."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Từ chối khai sai dù chịu áp lực, báo cáo rủi ro và lưu bằng chứng.",en:"Refuse misdeclaration under pressure, escalate risks and keep evidence."}},{name:{vi:"Phối hợp & giải trình",en:"Coordination & explanation"},desc:{vi:"Làm việc với hải quan, hãng tàu, kho bãi và giải trình rõ ràng bằng văn bản.",en:"Work with customs, carriers and warehouses and explain clearly in writing."}}],knowledge:{vi:["Luật Hải quan số 54/2014/QH13 và các nghị định hướng dẫn.","Thông tư 38/2015/TT-BTC (sửa đổi bởi Thông tư 39/2018/TT-BTC) về thủ tục hải quan.","Thông tư 39/2015/TT-BTC về trị giá hải quan hàng hóa xuất nhập khẩu.","Danh mục hàng hóa xuất nhập khẩu Việt Nam theo AHTN/HS 2022 và 6 quy tắc tổng quát.","Quy tắc xuất xứ trong các FTA (ATIGA, CPTPP, EVFTA) và các mẫu C/O tương ứng."],en:["Customs Law No. 54/2014/QH13 and its implementing decrees.","Circular 38/2015/TT-BTC (amended by Circular 39/2018/TT-BTC) on customs procedures.","Circular 39/2015/TT-BTC on customs valuation of imports and exports.","Vietnam's import-export nomenclature based on AHTN/HS 2022 and the six general rules.","Rules of origin under FTAs (ATIGA, CPTPP, EVFTA) and the matching C/O forms."]},tools:["VNACCS/VCIS","Phần mềm khai báo ECUS","Cổng Một cửa Quốc gia (VNSW)","Biểu thuế XNK điện tử","Microsoft Excel"],kpis:{vi:["Tỷ lệ tờ khai đúng ngay lần đầu, không phải khai bổ sung.","Thời gian thông quan trung bình mỗi lô.","Số lỗi phát hiện khi kiểm tra sau thông quan (mục tiêu bằng 0).","Tỷ lệ hồ sơ lưu trữ đầy đủ, tra cứu được trong 5 phút."],en:["Right-first-time declaration rate with no amendments.","Average clearance time per shipment.","Errors found in post-clearance audits (target zero).","Share of complete files retrievable within 5 minutes."]},day:[{time:"08:00",vi:"Rà soát chứng từ lô hàng đến cảng hôm nay, đối chiếu hóa đơn với phiếu đóng gói.",en:"Review documents for today's arrivals and match invoices with packing lists."},{time:"10:00",vi:"Phân loại mã HS cho mặt hàng mới, lập bảng tính trị giá và thuế.",en:"Classify a new item, build the valuation and duty worksheet."},{time:"13:30",vi:"Truyền tờ khai, nhận kết quả phân luồng và chuẩn bị hồ sơ giải trình.",en:"Submit declarations, receive channel results and prepare explanations."},{time:"15:30",vi:"Phối hợp kiểm tra thực tế hàng hóa tại kho với đội hiện trường.",en:"Coordinate a physical inspection at the warehouse with the field team."},{time:"17:00",vi:"Cập nhật sổ theo dõi tờ khai và lưu hồ sơ điện tử.",en:"Update the declaration log and archive the electronic file."}],mistakes:{vi:["Tính thuế trên giá FOB mà quên cộng cước và bảo hiểm.","Chọn mã HS theo tên thương mại thay vì theo cấu tạo, công dụng và chú giải.","Đổi mã HS theo yêu cầu kinh doanh để giảm thuế, dẫn tới truy thu và xử phạt."],en:["Computing duty on the FOB price without adding freight and insurance.","Choosing an HS code from the trade name instead of composition, function and notes.","Changing the HS code at Sales' request to cut duty, leading to back taxes and penalties."]},career:[{vi:"Nhân viên chứng từ hải quan",en:"Customs documentation assistant"},{vi:"Chuyên viên khai báo hải quan",en:"Customs declaration specialist"},{vi:"Trưởng nhóm tuân thủ hải quan",en:"Customs compliance team lead"},{vi:"Quản lý xuất nhập khẩu & tuân thủ thương mại",en:"Trade compliance & import-export manager"}],glossary:[{term:"HS code",vi:"Mã số phân loại hàng hóa theo Hệ thống hài hòa của Tổ chức Hải quan Thế giới.",en:"Goods classification code under the World Customs Organization Harmonized System."},{term:"CIF",vi:"Điều kiện giao hàng gồm giá hàng, phí bảo hiểm và cước vận tải đến cảng đích.",en:"Delivery term covering cost, insurance and freight to the destination port."},{term:"VNACCS/VCIS",vi:"Hệ thống thông quan tự động và cơ sở dữ liệu thông tin nghiệp vụ của Hải quan Việt Nam.",en:"Vietnam Customs automated clearance system and intelligence database."},{term:"Phân luồng",vi:"Kết quả xử lý tờ khai: xanh (thông quan), vàng (kiểm tra hồ sơ), đỏ (kiểm tra thực tế).",en:"Declaration routing result: green (cleared), yellow (document check), red (physical inspection)."},{term:"C/O",vi:"Giấy chứng nhận xuất xứ hàng hóa, căn cứ hưởng thuế suất ưu đãi theo hiệp định.",en:"Certificate of origin used to claim preferential FTA duty rates."}],quiz:[{q:{vi:"Trị giá hải quan hàng nhập khẩu thường gồm những khoản nào?",en:"What does the customs value of imported goods usually include?"},options:{vi:["Chỉ giá FOB","Giá FOB + cước + bảo hiểm đến cửa khẩu nhập","Giá bán lẻ tại Việt Nam","Giá FOB trừ chiết khấu thương mại"],en:["FOB price only","FOB price + freight + insurance to the port of import","Retail price in Vietnam","FOB price minus trade discount"]},answer:1,explain:{vi:"Trị giá giao dịch phải cộng các chi phí vận chuyển và bảo hiểm đến cửa khẩu nhập đầu tiên.",en:"Transaction value must include transport and insurance costs to the first port of import."}},{q:{vi:"Căn cứ ưu tiên khi phân loại mã HS là gì?",en:"What takes priority when classifying an HS code?"},options:{vi:["Tên hàng trên hóa đơn","Chú giải phần, chương và nội dung nhóm","Mã HS nhà cung cấp gợi ý","Mã có thuế suất thấp nhất"],en:["The name on the invoice","Section and chapter notes and heading texts","The code suggested by the supplier","The code with the lowest rate"]},answer:1,explain:{vi:"Quy tắc 1 yêu cầu phân loại theo nội dung nhóm và chú giải phần, chương.",en:"Rule 1 requires classification by heading texts and section or chapter notes."}},{q:{vi:"Tờ khai bị phân luồng đỏ nghĩa là gì?",en:"What does a red channel result mean?"},options:{vi:["Được thông quan ngay","Kiểm tra hồ sơ giấy","Kiểm tra thực tế hàng hóa","Tờ khai bị hủy"],en:["Immediate clearance","Paper document check","Physical inspection of goods","Declaration cancelled"]},answer:2,explain:{vi:"Luồng đỏ yêu cầu kiểm tra hồ sơ và kiểm tra thực tế hàng hóa.",en:"The red channel requires both document and physical inspection."}},{q:{vi:"Kinh doanh yêu cầu khai mã HS thuế thấp hơn để kịp giờ. Bạn làm gì?",en:"Sales asks you to declare a lower-duty HS code to save time. What do you do?"},options:{vi:["Làm theo rồi khai bổ sung sau","Khai đúng mã, giải trình và báo cáo cấp trên","Bỏ qua và chờ hết giờ","Hỏi hãng tàu chọn mã"],en:["Comply and amend later","Declare the correct code, document it and escalate","Ignore it until the deadline","Ask the carrier to choose the code"]},answer:1,explain:{vi:"Khai sai mã để giảm thuế là vi phạm; phải khai đúng, lưu căn cứ và báo cáo áp lực.",en:"Misdeclaring to cut duty is a violation; declare correctly, keep evidence and escalate the pressure."}}],tools_en:["VNACCS/VCIS","ECUS customs declaration software","Vietnam National Single Window (VNSW)","Electronic import-export tariff schedule","Microsoft Excel"]}}})})(window.KKR);
